import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v; self.nxt = nxt

def build(vals):
    head = None
    tail = None
    for v in vals:
        node = N(v)
        if head is None:
            head = node
        else:
            tail.nxt = node
        tail = node
    return head

def to_list(head):
    out = []
    cur = head
    while cur:
        out.append(cur.v)
        cur = cur.nxt
    return out

def delete_brute(head):
    from collections import Counter
    vals = []
    cur = head
    while cur:
        vals.append(cur.v)
        cur = cur.nxt
    cnt = Counter(vals)
    keep = [v for v in vals if cnt[v] == 1]
    return build(keep)

