def delete_best(head):
    dummy = N(0, head)
    prev = dummy
    while head:
        if head.nxt and head.v == head.nxt.v:
            while head.nxt and head.v == head.nxt.v:
                head = head.nxt
            prev.nxt = head.nxt
        else:
            prev = head
        head = head.nxt
    return dummy.nxt

